#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Offline editor for Book→Skill 3–7 step method refinement."""
from __future__ import annotations

from pathlib import Path
import argparse
import html
import json


def e(x): return html.escape(str(x or ""))


def render(data: dict) -> str:
    evidence_cards=[]
    for row in data.get('evidence') or []:
        label='我的想法' if row.get('kind')=='user_review' else '我的划线'
        evidence_cards.append(f'''<label class="evidence"><input type="checkbox" value="{e(row.get('evidenceId'))}"><span><b>{e(row.get('evidenceId'))} · {label}</b><small>{e(row.get('chapter') or '未标章节')}</small><em>{e(row.get('text'))}</em></span></label>''')
    payload=json.dumps(data,ensure_ascii=False).replace('</','<\/')
    return f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow,noarchive"><title>Book Method Refinement</title><style>:root{{--bg:#f4efe7;--paper:#fffaf3;--paper2:#f8f1e7;--ink:#28241f;--muted:#756d64;--line:#ddd2c4;--accent:#a6523d}}@media(prefers-color-scheme:dark){{:root{{--bg:#171513;--paper:#231f1c;--paper2:#2a2521;--ink:#f2ece5;--muted:#aaa096;--line:#403832;--accent:#df7053;color-scheme:dark}}}}*{{box-sizing:border-box}}body{{margin:0;background:var(--bg);color:var(--ink);font-family:Inter,"PingFang SC",sans-serif}}main{{max-width:1120px;margin:auto;padding:34px 22px}}.notice,.step,.evidence-panel{{background:var(--paper);border:1px solid var(--line);border-radius:16px;padding:16px;margin:13px 0}}.notice{{border-style:dashed}}.toolbar{{display:flex;gap:8px;flex-wrap:wrap;position:sticky;top:0;padding:10px 0;background:color-mix(in srgb,var(--bg) 94%,transparent);backdrop-filter:blur(8px);z-index:3}}button{{border:1px solid var(--line);border-radius:999px;padding:8px 12px;background:var(--paper);color:var(--ink);cursor:pointer}}input,textarea{{width:100%;border:1px solid var(--line);border-radius:10px;padding:8px;background:var(--paper2);color:var(--ink);font:inherit}}textarea{{min-height:72px;resize:vertical}}.step-head{{display:flex;justify-content:space-between;gap:12px;align-items:center}}.step label{{display:block;font-size:11px;color:var(--muted);margin:8px 0}}.evidence-grid{{display:grid;grid-template-columns:repeat(2,1fr);gap:7px}}.evidence{{display:flex;gap:8px;border:1px solid var(--line);border-radius:12px;padding:9px;background:var(--paper2)}}.evidence input{{width:auto}}.evidence b,.evidence small,.evidence em{{display:block}}.evidence small{{color:var(--muted);font-size:10px}}.evidence em{{font-style:normal;font-size:11px;line-height:1.5;margin-top:4px}}@media(max-width:760px){{.evidence-grid{{grid-template-columns:1fr}}}}</style></head><body><main><h1>方法型 Book→Skill · {e((data.get('book') or {}).get('title'))}</h1><div class="notice">不要“总结整本书”。这里只允许把当前 evidence 重组为 3–7 个可执行步骤。每一步都必须绑定 evidenceId；有用户 review 时，最终方法至少应使用一条 review。</div><label>方法名称<input id="methodTitle" placeholder="例如：做 X 时的五步检查法"></label><label>适用目的<textarea id="purpose" placeholder="这个方法用于解决什么具体问题？"></textarea></label><div class="toolbar"><button id="addStep">新增步骤</button><button id="export">导出 refinement JSON</button></div><section id="steps"></section><section class="evidence-panel"><h2>Evidence Pool</h2><div class="evidence-grid">{''.join(evidence_cards)}</div></section></main><script>const data={payload};const steps=document.getElementById('steps');function esc(s){{return String(s??'').replace(/[&<>"']/g,c=>({{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}}[c]))}}function renderSteps(){{steps.innerHTML='';(data.method.steps||[]).forEach((s,i)=>{{const el=document.createElement('article');el.className='step';el.dataset.index=i;el.innerHTML=`<div class="step-head"><h2>步骤 ${{i+1}}</h2><button data-remove>删除</button></div><label>Action<input data-field="action" value="${{esc(s.action||'')}}"></label><label>Why<textarea data-field="why">${{esc(s.why||'')}}</textarea></label><label>Evidence IDs（逗号分隔）<input data-field="evidenceIds" value="${{esc((s.evidenceIds||[]).join(','))}}"></label>`;steps.appendChild(el)}})}}document.getElementById('addStep').onclick=()=>{{if((data.method.steps||[]).length>=7)return alert('最多 7 步');data.method.steps=data.method.steps||[];data.method.steps.push({{action:'',why:'',evidenceIds:[]}});renderSteps()}};steps.addEventListener('input',ev=>{{const card=ev.target.closest('.step');if(!card)return;const s=data.method.steps[+card.dataset.index],f=ev.target.dataset.field;if(f==='evidenceIds')s[f]=ev.target.value.split(',').map(x=>x.trim()).filter(Boolean);else if(f)s[f]=ev.target.value}});steps.addEventListener('click',ev=>{{if(!ev.target.matches('[data-remove]'))return;data.method.steps.splice(+ev.target.closest('.step').dataset.index,1);renderSteps()}});document.querySelectorAll('.evidence input').forEach(cb=>cb.addEventListener('change',()=>{{const ids=[...document.querySelectorAll('.evidence input:checked')].map(x=>x.value);navigator.clipboard?.writeText(ids.join(','))}}));document.getElementById('methodTitle').oninput=e=>data.method.title=e.target.value;document.getElementById('purpose').oninput=e=>data.method.purpose=e.target.value;document.getElementById('export').onclick=()=>{{const blob=new Blob([JSON.stringify(data,null,2)],{{type:'application/json'}}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='weread-book-method-refinement.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}};renderSteps();</script></body></html>'''


def main():
    p=argparse.ArgumentParser();p.add_argument('--input',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();data=json.loads(a.input.read_text(encoding='utf-8'));a.output.parent.mkdir(parents=True,exist_ok=True);a.output.write_text(render(data),encoding='utf-8');print(f"book-method-editor: {a.output} | evidence={len(data.get('evidence') or [])}")
if __name__=='__main__':main()
